SELECT b.id AS basecamp_id, b.title AS title, s.id AS spot_id, s.name AS spot_name, s.type AS spot_type, ST_Latitude(s.location) AS spot_lat, ST_Longitude(s.location) AS spot_lng, b.start_date AS start_date, b.end_date AS end_date, b.capacity AS capacity, AS headcount, b.status AS status, b.min_trust_level AS min_trust_level, b.age_group_min AS age_group_min, b.age_group_max AS age_group_max, b.same_gender_only AS same_gender_only, b.required_gender AS required_gender FROM basecamp b JOIN spot s ON s.id = b.spot_id WHERE b.status = 'RECRUITING' AND s.status = 'ACTIVE'
AND b.start_date >= #{condition.fromDate}
AND b.start_date <= #{condition.toDate}
AND < b.capacity
ORDER BY b.start_date, b.id LIMIT #{limit} OFFSET #{offset}

SELECT b.id AS basecamp_id,
       m.status AS member_status,
       a.status AS application_status
FROM basecamp b
LEFT JOIN basecamp_member m ON m.basecamp_id = b.id AND m.member_id = #{viewerId}
LEFT JOIN basecamp_application a ON a.basecamp_id = b.id AND a.applicant_id = #{viewerId}
WHERE b.id IN

        #{basecampId}

  AND (m.id IS NOT NULL OR a.id IS NOT NULL)
